INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Liz: Before the Plague', 'One night, in a near future a special investigation Unit named Liz has to face a strange case that seems a common one, but it''s not. She has to respond to a distress call from a pharmaceutical company and investigate, collecting infos and survive using her own tools. Figure out what happened in order to resolve the case and find the truth about the laboratory accident.' FROM games WHERE igdb_id = 94874 ON CONFLICT (game_id, language_code) DO NOTHING;
