INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney Tsum Tsum Festival', 'Disney Tsum Tsum Festival brings Disney’s highly popular stuffed Tsum Tsum toys featuring iconic Disney characters to the Nintendo Switch for the first time ever. Disney Tsum Tsum Festival stars a large roster of Disney characters, including Mickey and Minnie Mouse, in a myriad of party games which can be played with friends and family both at home or on-the-go. These party games can be played by up to four players on a single Nintendo Switch, or players can choose to play online with Tsum Tsum fans around the world.' FROM games WHERE igdb_id = 115332 ON CONFLICT (game_id, language_code) DO NOTHING;
