INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'One Drop Bot', 'Playing a cute robot, you travel from room to room solving tough puzzles and overcoming tricky platforming that will test your skills. Collecting health is necessary, because when you die, all the health you’ve collected comes back. The catch is that you have to start over at the very beginning.' FROM games WHERE igdb_id = 117367 ON CONFLICT (game_id, language_code) DO NOTHING;
