INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Variable Barricade', 'A member of a prestigious family and heir to a fortune, Hibari learns that her eccentric grandfather is determined to find her a husband. He arranges to house her in a luxurious villa along with four handsome, hand-picked bachelors and her private butler. As her suitors try to win her hand by any means necessary, Hibari endures endless everyday trials and temptations.INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 69345 AND ge.slug = 'adventure' ON CONFLICT DO NOTHING;
