INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Active Soccer 2019', 'Active Soccer 2019 is an exciting top-down arcade football game providing a fast-paced arcade experience, implementing amazing playability and responsive easy-to-learn/hard-to-master controls. Active Soccer 2019 provides a complete career mode, implementing many international leagues, cups and championships. Imagine being the manager of a 5th division English team - you have a budget and your goal is to be promoted to higher divisions, by purchasing players, creating tactics, managing the team and playing real matches.' FROM games WHERE igdb_id = 117537 ON CONFLICT (game_id, language_code) DO NOTHING;
