INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sonic: Project Hero', 'Sonic - Project Hero is a 3D Sonic fangame & custom, closed source framework, made for the Unity game engine and developed by Hero. It aims to launch Sonic, Tails & Knuckles into, simply, a fun 3D adventure through various locales, to stop Dr. Eggman''s new scheme. The game aims to introduce new and unique mechanics and mix-n''-match existing ones from the Sonic series, in order to create a fresh experience.' FROM games WHERE igdb_id = 227991 ON CONFLICT (game_id, language_code) DO NOTHING;
