INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'PyroMind', 'Simultaneously turn-based and real-time, PyroMind is a delightfully unforgiving action puzzler about defusing bombs and escaping chain reactions. Play alone, blow up your friend or challenge a bot in a unique dimension, where everything explodes and one small mistake can blast you to smithereens.' FROM games WHERE igdb_id = 103051 ON CONFLICT (game_id, language_code) DO NOTHING;
