INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('taleans-hansel-and-gretel-story', 98575, '2019-10-16', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6eb3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scm66x.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Taleans Hansel and Gretel story', 'While the boy Hansel and his sister girl Gretel were walking in the dark forest, they lost each other. In "Taleans Hansel and Gretel" you will have to help them find each other. On the screen you will see a forest glade, at the different ends of which our characters are standing. For our heroes to meet each other, they need to walk along the path that goes through the clearing. But the path is broken, and you need to restore its integrity by moving the elements on the screen and putting them in the right place. As soon as you finish this task, the heroes will run along the path and meet up.' FROM games WHERE igdb_id = 98575 ON CONFLICT (game_id, language_code) DO NOTHING;
