INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Toro and Friends: Onsen Town', 'Toro and Friends: Onsen Town is a Match-3 Puzzle mobile game Developed by BeXide and published by Forward Works for Android and iOS. It was first released in 2019 in Japan for the Doko Demo Issyo series 20th anniversary, then later released worldwide in English, Chinese, and Korean in 2020 which was published by PiG Corporation. The game''s service ran until 2021. After the closure of the Japanese servers, an offline mode was added to the game and all story episodes were made available.' FROM games WHERE igdb_id = 119233 ON CONFLICT (game_id, language_code) DO NOTHING;
