INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Irori', 'As the aroma of savoury skewers wafts outside, hungry passengers rest their weary souls at the hearth. You are the chef on the cross-lands train, in charge of the irori cabin. Cook up a variety of skewers to warm bellies and hearts as you cross paths with travellers on their own journeys.' FROM games WHERE igdb_id = 184067 ON CONFLICT (game_id, language_code) DO NOTHING;
