INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crackdown 3', 'Stop crime as a super-powered Agent of justice in Crackdown 3''s hyper-powered sandbox of mayhem and destruction. Explore the heights of a futuristic city, race through the streets in a transforming vehicle, and use your powerful abilities to stop a ruthless criminal empire. Developed by original creator Dave Jones, Crackdown 3 delivers cooperative mayhem and an all-new multiplayer mode where destruction is your ultimate weapon.' FROM games WHERE igdb_id = 7333 ON CONFLICT (game_id, language_code) DO NOTHING;
