INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Notzing Project', 'Deep underground, a government science facility lies dormant and abandoned. But when a man wakes up from being held in stasis, he must face whatever technological horrors caused the facility to shut itself off from the surface, and make it out alive. In this first person exploration game, you will find audio cassettes left by the scientists who once operated the establishment. Use the clues you can find to get out alive.' FROM games WHERE igdb_id = 323555 ON CONFLICT (game_id, language_code) DO NOTHING;
