INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Irony Curtain: From Matryoshka with Love', 'Irony Curtain: From Matryoshka with Love is a satirical point-and-click inspired by the classic adventure games. It smuggles you out of your comfort zone and throws into the middle of a Cold War spy intrigue – and there’s an even bigger game being played… Experience Matryoshka through Evan – a low-ranking, goofy journalist involuntarily pulled right into the middle of an espionage stand-off between two powers. Hop onto the wacky spy adventure, uncover secrets of the bizzare communist country (and the powerful capitalistic empire!), witness the story full of unpredictable twists and turns and discover the true agenda of the mysterious Supreme Leader!' FROM games WHERE igdb_id = 106108 ON CONFLICT (game_id, language_code) DO NOTHING;
