INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Book Seeker', 'You will play a commissioned detective in the game. Your client wants you to help find the treasures of his grandfather: a very special book, The client’s book was stolen from the window one night. When you delve into this matter, you find that there are some secrets in it. Even related to an unspeakable race...' FROM games WHERE igdb_id = 121536 ON CONFLICT (game_id, language_code) DO NOTHING;
