INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('world-for-two', 147270, '2019-05-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7ipi.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar9a7.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World for Two', 'A sudden catastrophe has led life on Earth to the verge of extinction. The Professor, the only survivor, spent years performing research in an underground laboratory trying to recreate life. The energy he needs to do this can only be harvested outdoors, where he himself cannot go. He therefore created an android to help him. Plants are the only living things left in this world where human civilization is no more. It is cruel, but beautiful. The Professor and the android embark on a quest to bring animals back to the planet. This is a tale of creating life on a dead planet. World for Two is coming to Nintendo Switch! The animations for all creatures have been redrawn, to help them come alive even better. Once you complete the main story, you will be able to enjoy “Chapter 0”, a new special story that includes new art and music and will tell you more about the Professors’s past. And as an added bonus, once you complete the game, you will unlock the option to change the main story’s soundtrack to a fascinating new version played by a piano quintet (piano, two violins, viola and violoncello)' FROM games WHERE igdb_id = 147270 ON CONFLICT (game_id, language_code) DO NOTHING;
