INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Demon Hunter 5: Ascendance', 'You slump into your chair after another day of investigations. Just as you start to lose yourself in the glow of the TV screen, the telephone rings. The museum curator needs your help - a tourist has gone missing. You smirk at his warning of paranormal goings-on; that''s what Demon Hunters are for.' FROM games WHERE igdb_id = 116856 ON CONFLICT (game_id, language_code) DO NOTHING;
