INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Baba Is You', 'Baba Is You is a puzzle game where you can change the rules by which you play. In every level, the rules themselves are present as blocks you can interact with; by manipulating them, you can change how the level works and cause surprising, unexpected interactions! With some simple block-pushing you can turn yourself into a rock, turn patches of grass into dangerously hot obstacles, and even change the goal you need to reach to something entirely different.' FROM games WHERE igdb_id = 76638 ON CONFLICT (game_id, language_code) DO NOTHING;
