INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'brainCloud Bombers', 'It''s Bombin'' Time! Climb into the pilot seat! Team up, shoot down your opponents, collect their bombs, then bomb their ships to smithereens! The first team to sink all enemy ships wins the round. Supports 8 player simultaneous matches with empty slots filled in by bots! It''s time to get bombin''!' FROM games WHERE igdb_id = 120400 ON CONFLICT (game_id, language_code) DO NOTHING;
