INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '​The Ninja Saviors: Return of the Warriors', 'Based on the 1994-released The Ninja Warriors: Again, which is a Super Famicom arrangement of the 1987-released arcade game The Ninja Warriors, ​The Ninja Saviors: Return of the Warriors is a 25-year-later remake from the Tengo Project main staff that brought you the original games. While retaining its 16-bit style, The Ninja Warriors: Once Again significantly enhances the character resolution, pattern amount, and more to match the latest hardware. In addition to two new playable characters, ​The Ninja Saviors: Return of the Warriors implements a two-player co-op mode that was not available in The Ninja Warriors: Again.' FROM games WHERE igdb_id = 123354 ON CONFLICT (game_id, language_code) DO NOTHING;
