INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Darksiders: Genesis - Nephilim Edition', 'In Darksiders Genesis, the fourth Horseman of the Apocalypse STRIFE is called upon to save humankind from certain destruction at the hands of Lucifer. True to its roots, Darksiders Genesis will feature intense combat, exploration, puzzle-solving, epic boss battles and serpent holes from heaven to hell. The game marks the first, full-scale Darksiders adventure played from the top-down perspective.
