INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('plasticity', 119192, '2019-05-24', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4h0u.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5pd.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Plasticity', 'Plasticity is a 2.5D cinematic platformer about a young girl named Noa who explores and decides the future of her post-oil, plastic-ridden world. Set in the year 2140, in a world where plastic consumption never ended, leaving lifeless cities, flooded towns, and widespread disease in its wake, players will make choices that either help or harm the environment and it''s living creatures. After a certain point of the game is reached, 10 years will pass and players will see and play through the impact of their own choices.
