INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Year of Rain', 'A Year Of Rain is a team RTS uniting classical elements like base building and expansive story campaigns with strong hero focus and team-oriented gameplay. As well as co-op campaigns for all three factions, A Year Of Rain features additional 2v2 modes like “Skirmish” and “Against all Odds”.' FROM games WHERE igdb_id = 116212 ON CONFLICT (game_id, language_code) DO NOTHING;
