INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Potion Punch 2: Cooking Quest', 'Potion Punch 2 takes the cooking fever to an all time high with baby dragons roasting ingredients, and magic wisps freezing your favorite treats or grilling your delicious steaks! Cook in ways that you''ve never seen before in a fast paced time-management game. Become the star chef through hundreds of levels teeming with amazing heroes and dastardly villains. Unfurl your scrolls, polish your frying pans, and open the restaurant doors, because it''s time for cooking madness in Potion Punch 2!' FROM games WHERE igdb_id = 247219 ON CONFLICT (game_id, language_code) DO NOTHING;
