INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Obsidian Crown', '‘Obsidian Crown’ is a top-down, roguelite shooter for Windows / PC that doesn''t require the player to kill everything in sight! Featuring Pixel graphics and a unique ‘karma’ game mechanic, Obsidian Crown challenges each player to find the right balance of weapons in order to complete the game, save planet Earth, and rescue your beloved...' FROM games WHERE igdb_id = 124164 ON CONFLICT (game_id, language_code) DO NOTHING;
