INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fort Boyard', 'Ever wanted to experience the Fort Boyard adventure with your friends? You will soon be able to make that dream a reality: set off on the journey together, from the comfort of your couch, in just a few weeks’ time! In single or multiplayer mode (up to 4 players), solve Sir Fouras’ tricky riddles, follow Passe-Partout through the mazes of the fort and take up the challenges to get the keys that will allow you to enter the treasure room.' FROM games WHERE igdb_id = 119925 ON CONFLICT (game_id, language_code) DO NOTHING;
