INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Choice or Fate', 'Choice of Fate is an indie adventure RPG that throws you into the fascinating and cruel world of Ennerd. Will you save this world? Or destroy it? Along the way you will face many obstacles and many solutions. Each even insignificant choice affects the development and ending of the game, so be careful with your choice.' FROM games WHERE igdb_id = 114404 ON CONFLICT (game_id, language_code) DO NOTHING;
