INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ms. Holmes: The Monster of the Baskervilles - Collector''s Edition', 'Nicknamed Ms. Holmes for your sharp whit and investigative prowess, you''re England''s favorite new detective! But even your smarts will be tested when one of Sherlock Holmes'' old cases comes back with a vengeance. The Baskervilles are once again plagued by a strange and dangerous monster, one bent on much more than the destruction of one family. Can you uncover who is behind recent attacks on the Baskerville estate and save London before it''s too late? Find out in this thrilling Hidden-Object Puzzle adventure!INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 119688 AND ge.slug = 'point-and-click' ON CONFLICT DO NOTHING;
