INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Swords and Souls Neverseen', 'From SoulGame Studio, creators of the wildly popular Swords & Souls, comes an all new, even bigger standalone adventure to an island far across the sea. In Swords & Souls: Neverseen you find yourself shipwrecked and caught up in a struggle between a dangerous witch and some decidedly kooky townsfolk. To stop the witch, you''ll need to train, fight, train, and fight some more in this addictive single-player combat-focused game that rewards player skill and juicy progression.' FROM games WHERE igdb_id = 371846 ON CONFLICT (game_id, language_code) DO NOTHING;
