INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Christmas Stories: Enchanted Express - Collector''s Edition', 'Can you help the train''s passengers save their holidays in time? Find out in Christmas Stories: Enchanted Express - Collector''s Edition, an enchanting hidden-object puzzle adventure! This is a special Collector''s Edition release full of exclusive extras you won''t find in the standard version. Work on a case for the Cat King in the bonus game. Revisit the festive challenges with re-playable HOPs and mini-games, and earn achievements. Search for puzzle pieces and morphing items hidden among the decorations. Enjoy exclusive wallpapers, screen savers, music, a Secret Room Quest, a strategy guide, and more!' FROM games WHERE igdb_id = 127469 ON CONFLICT (game_id, language_code) DO NOTHING;
