INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jumpgrid', 'Jumpgrid is bullet hell hyper-Pac-Man. Survive an ever-moving cosmic obstacle course by deftly teleporting between nodes on the "jump-grid". Clear all nodes to open a wormhole to the next level. Success requires only a few seconds of precision finger ballet, but touch any of the pulsing hazards and the level instantly resets, ready for you to try again, and again, and again... This is a game about honing your muscle memory until you learn to dance with your fingers!' FROM games WHERE igdb_id = 111420 ON CONFLICT (game_id, language_code) DO NOTHING;
