INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kanji in Motion', 'Kanji in Motion is a program for learning to read, in a game-like way, the characters of the two sets of kana, plus the 2,136 Jōyō Kanji. The task of the player-learner is to quickly identify characters that move across a playing field and match them to their respective reading and meaning.' FROM games WHERE igdb_id = 368288 ON CONFLICT (game_id, language_code) DO NOTHING;
