INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '7 Wonders Duel', '7 Wonders Duel is solely for two players, with the players not drafting cards simultaneously from hands of cards, but from a display of face-down and face-up cards arranged at the start of a round. A player can take a card only if it''s not covered by any others, so timing comes into play as well as bonus moves that allow you to take a second card immediately. As in the original game, each card that you acquire can be built, discarded for coins, or used to construct a wonder.' FROM games WHERE igdb_id = 214649 ON CONFLICT (game_id, language_code) DO NOTHING;
