INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Troy-Bilt: Testing Grounds', 'Troy-Bilt: Testing Grounds is a promotional browser game by BannerWave made in collaboration with Troy-Bilt to promote their lawnmowers during their "overtested campaign. The game has the player go over as many obstacles as possible to prove the power of their lawnmower and score up as many points they can within the time limit.' FROM games WHERE igdb_id = 327791 ON CONFLICT (game_id, language_code) DO NOTHING;
