INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Citadel: Forged With Fire', 'Citadel: Forged With Fire is a massive online sandbox RPG with elements of magic, spellcasting and inner-kingdom conflict. You have complete freedom to pursue your own destiny; hatch plots of trickery and deceit to ascend the ranks among allies and enemies, become an infamous hunter of other players, build massive and unique castles, tame mighty beasts to do your bidding, and visit uncharted territories to unravel their rich and intriguing history. The path to ultimate power and influence is yours to choose.' FROM games WHERE igdb_id = 47823 ON CONFLICT (game_id, language_code) DO NOTHING;
