INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bebder-game-bebder-than-the-rest', 209389, '2019-09-06', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4z7v.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/schwjn.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bebder Game: Bebder Than the Rest', 'The number 1 Anti-Wendy''s RPG game in the world. Bebder was a robot who had always enjoyed eating at fast food restaurants. However, one day he decided to try Wendy''s for the first time and he absolutely hated it. The food was gross and the service was terrible. Bebder was so angry that he killed the employee who served him. Now Bebder has a vendetta against Wendy''s. He wants to kill the CEO of Wendy''s in order to get revenge for the terrible experience he had at the restaurant. Bebder is a cold-blooded killer and he will stop at nothing until his mission is complete.' FROM games WHERE igdb_id = 209389 ON CONFLICT (game_id, language_code) DO NOTHING;
