INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Krampus is Home', 'Krampus is Home is a chilling first-person survival horror experience inspired by Central European folklore. You’ll step into the shoes of Sebastian, a teenager left home alone on Christmas Eve, only to be hunted by Krampus and his sinister helpers. With intense stealth mechanics, survival strategies, and action-packed gameplay, you’ll need to evade Krampus’s grasp and fight for your survival. Uncover the dark mystery behind your abduction and find a way to escape from Krampus’s realm.' FROM games WHERE igdb_id = 105081 ON CONFLICT (game_id, language_code) DO NOTHING;
