INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Future Snooker', 'Future Snooker is a futuristic snooker game. Players take turns to shoot a cue-ball on a circular snooker table. Score points by potting red then colour, just as in normal snooker. A compelling mix of tactics and skill for one or two players with a selection of computer opponents.' FROM games WHERE igdb_id = 126386 ON CONFLICT (game_id, language_code) DO NOTHING;
