INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shadow Corridor', 'Chased by the spirits of the cursed Noh mask, you must do everything you can to escape. Set in traditional Japanese locales, Shadow Corridor provides a unique survival horror experience. Randomly generated maps filled with a variety of items make every playthrough different. Immerse yourself in the darkness, for only the determined will survive.' FROM games WHERE igdb_id = 172854 ON CONFLICT (game_id, language_code) DO NOTHING;
