INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deputy Arsh', 'Deputy Arsh is a simple monochrome endless runner game for the Atari ST. It was written in C/68000 ASM, with the goal of using no operating system features (aside from the supervisor toggle to access restricted memory). Everything in Deputy Arsh was written from scratch, including the raster library, sound generation library, custom interrupt vectors, and keyboard/mouse drivers.' FROM games WHERE igdb_id = 329192 ON CONFLICT (game_id, language_code) DO NOTHING;
