INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('jollibees-phase-1', 185847, '2019-08-03', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4asa.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scf30m.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jollibee''s: Phase 1', '20 years after the incident (aka, in 2037), the player (Justin Smith) is working the night-shift at Jollibee''s. Every night, you must keep track of the animatronics to stop them from getting in your office. You must check the cameras to locate them. On the cameras, you can check for them throughout the building and in the vents by clicking the "CHANGE FLOOR" button. Aside from checking the cameras, you must shut vents, "close" lights, and flash your light to keep them away. There is a vent to your left, a door in front of your desk, and a window to your right. The vent and window require flashing the light to keep the characters from getting you into trouble. However, the door requires shutting the lights off so they think the office is an empty room.
