INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cat Notebook', 'Explore a cat''s notebook. Become an impeccant feline whose existence is bound by registers of ailuric abstraction. Uncover a prodigious maze of audiovisual crystallization at soul-rending pace. Cat Notebook, a walking simulator, has many unique illustrations to look at and songs to listen to. Do cat-like things with 40+ hours of gameplay - suffer alone or together as a great party game.' FROM games WHERE igdb_id = 114264 ON CONFLICT (game_id, language_code) DO NOTHING;
