INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Darkula', 'Darkula is a frantic fixed platform game designed like a 1983 coin-op arcade. It mimics the technical specs of the time in terms of image and sound, but it goes further with a smooth playability and a scoring system carefully designed for local tournaments. Collect all the light bulbs to complete a level. Collect shining light bulbs consecutively to raise the challenge and earn a growing bonus. Be fast, don''t miss the special object and be careful with the monsters around!' FROM games WHERE igdb_id = 119481 ON CONFLICT (game_id, language_code) DO NOTHING;
