INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BattleTabs', 'BattleTabs is a modern, strategic twist on the classic Battleship game, featuring ability-based ship combat and cross-platform multiplayer. Players place 4 ships on a grid and take turns attacking opponents, with each ship having a unique ability and cooldown that adds strategic depth. Quick 3-5 minute matches across Web, iOS, Android, and Steam with ranked leagues, a branching research tree, and extensive fleet customization.' FROM games WHERE igdb_id = 140591 ON CONFLICT (game_id, language_code) DO NOTHING;
