INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Make Butter Together!', '忽然从天而降的萝装少女，总是带着敌意的学妹，经常放鸽子的学姐。剧情是甜蜜亦或是胃疼？ 买一赠一，恋爱模拟器精神(病)续作（才怪），作为玩家参与到游戏制作过程中去，你会写出怎样的校园恋爱故事呢？来体验制作组产出的心路历程吧。（X）' FROM games WHERE igdb_id = 120013 ON CONFLICT (game_id, language_code) DO NOTHING;
