INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ashen-sky', 299596, '2019-05-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co856i.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ashen Sky', 'Inspired by the thrilling, mystical and at the same time exciting and adventurous worlds of the Roadside Picnic novel, Stalker movie and, of course, famous S.T.A.L.K.E.R. games, Ashen Sky aims to recreate the sensation of being face to face with the vast unknown. The gameplay is harsh and combat is unforgiving, since casual shootouts without serious consequences are not what this codebase aims for; instead, it is about working in teams with different specializations between players as every character has a set of traits that define their parameters, in order to survive, uncover the secrets of the anomalous territories and learn how to make use and profit of your knowledge. It''s about being all alone with the absolutely uncaring, alien Zone - one where no admin will magically help you if you get killed by another player, where there are no rules, yet the game punishes playing dumb and aggressive, and the best strategy is being smart and patient.' FROM games WHERE igdb_id = 299596 ON CONFLICT (game_id, language_code) DO NOTHING;
