INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '11th Dream', '11th Dream is fast-paced third person abstract shooter aimed at fast runners and hard-core difficulty enthusiasts. 11th includes both skirmish maps and campaign aimed at fast runners and hard-core difficulty enthusiasts. It is a game that you can try to beat while you render your video, waiting for the meeting or for a reply from your friend. Besides the solo-hardcore experience, 11th Dream delivers fully scrip-table in-game map editor, daily scoreboards to compete with other players and full on-line stats and leader-boards.' FROM games WHERE igdb_id = 117856 ON CONFLICT (game_id, language_code) DO NOTHING;
