INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Saga of the Shattered Swords', 'A person who "resurrected from the dead" has led to 20 years of grievances and entanglements. A wish of "resurrection", revealing the historical truth of the 15th century. Shenzhou and Schicksal, Taixuan and Tianqiong, Seven Disciples and Five Essences... All the mysteries from 500 years ago are solved here.' FROM games WHERE igdb_id = 249267 ON CONFLICT (game_id, language_code) DO NOTHING;
