INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gythol Granditti: The Crypt of Darkness', 'Geoff Dandy is your typical lout. Until one day, life long friend Dolph Dombardo barges into his house in a drunken stupor. He rages incoherently then leaves mumbling about going to the deadly Jiggly Swamp. Saving Dolph from doom is just the beginning of events that lead to Geoff''s true purpose...' FROM games WHERE igdb_id = 120411 ON CONFLICT (game_id, language_code) DO NOTHING;
