INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'FIFA 20: Champions Edition', 'Powered by Frostbite, EA SPORTS FIFA 20 for PC brings two sides of The World’s Game to life - the prestige of the professional stage and an all-new, authentic street football experience in EA SPORTS VOLTA. FIFA 20 innovates across the game, FOOTBALL INTELLIGENCE unlocks an unprecedented platform for gameplay realism, FIFA Ultimate Team offers more ways to build your dream squad and EA SPORTS VOLTA returns the game to the street with an authentic form of small-sided football.' FROM games WHERE igdb_id = 119890 ON CONFLICT (game_id, language_code) DO NOTHING;
