INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Roller Splat!', 'Swipe up, down and all around to send your vibrant paintball rolling through the maze as you splash, splat and sploosh color all over the clean white maze. Complete the levels of each puzzle by covering every corridor and corner with beautifully bright paint. It feels so satisfying, who doesn''t love a clean coat of fresh paint?' FROM games WHERE igdb_id = 116420 ON CONFLICT (game_id, language_code) DO NOTHING;
