INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Infiniboss', 'Infiniboss is an endless boss battle platformer. It''s just you, an ever-changing boss, and tons of projectiles. Choose a character, get as many points as you can, use the points to unlock more characters, repeat. You can set a personal score goal for yourself for each character, you can send scores to friends to see if they can beat them, or you can just try to unlock every character. Play the game your way!' FROM games WHERE igdb_id = 134008 ON CONFLICT (game_id, language_code) DO NOTHING;
