INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Expanse', '25th century. The mankind has left the Earth to settle other planets. One of the Ark ships arrived in the star system but eventually no habitable planets were discovered. It led to a conflict between three factions — the scientists, the workers and the military — arisen on a planet with the best living conditions.' FROM games WHERE igdb_id = 343772 ON CONFLICT (game_id, language_code) DO NOTHING;
