INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('interrogation-you-will-be-deceived', 115118, '2019-12-05', 79, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1ukp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ard8n.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Interrogation: You Will Be Deceived', 'As a police detective tasked with bringing down a dangerous terrorist group, you fight on two fronts: interrogating suspects & managing your team and its reputation. With time running out, how far will you go to stop these criminals? Manipulation, threats or even torture? Does the end justify the means? Interrogation is a narratively immersive convo-puzzle game that challenges common preconceptions about highly relevant contemporary subjects like terrorism, police brutality and the power imbalances between citizens, the state and large corporations. The game tries to raise important moral, ideological and practical questions in the minds of the players.' FROM games WHERE igdb_id = 115118 ON CONFLICT (game_id, language_code) DO NOTHING;
