INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Daymare: 1998', 'Daymare: 1998 is a third-person survival horror game that recreates the mood of iconic titles from the ''90s, with a fresh storyline. An incident that turns a small town into a deadly zone, three characters to play with and little time to find the truth, before its mutated citizens abruptly end your mission.' FROM games WHERE igdb_id = 23891 ON CONFLICT (game_id, language_code) DO NOTHING;
