INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dead Days', 'Four strangers died that day. Now they live again, forced to hunt down specters just to keep their new bodies charged with the energy now fueling their second chance at life. Any joy they may have had at living again is soon stifled by the dispassionate employer that treats them as disposable combatants with no concern for the unnatural libido and arousal caused by their new bodies'' reaction to stressors.INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 221787 AND ge.slug = 'visual-novel' ON CONFLICT DO NOTHING;
