INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Harvest Moon: Mad Dash', 'Go solo or take a few friends along for the frenzy! Harvest, fish, milk, and more as you fullfil orders to complete each level! Things may start out easy, but you''ll hit the beach, the farm, and even the Underworld as you progress through the game! Have you ever tried to grow crops with molten lava falling on them?! That and other obstacles await you as you and your friends try to clear all the levels to restore the broken lighthouse!' FROM games WHERE igdb_id = 119173 ON CONFLICT (game_id, language_code) DO NOTHING;
