INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Blackbird of Amor', 'When there is an unsolved mystery, Stein can''t let it go, he must pursue it till the end. In Amor there is a certain woman that interests him, she is rumored to have eternal youth. To solve the mystery of this woman he must tear heaven from earth. His journey will take him far beyond the world he has known.' FROM games WHERE igdb_id = 128130 ON CONFLICT (game_id, language_code) DO NOTHING;
